import numpy as np
from scipy.optimize import least_squares
V=np.var(dA_dt)
def fit(f,npar,starts=30,seed=1):
    rng=np.random.default_rng(seed); best=None
    for k in range(starts):
        p0=rng.uniform(-1.5,2,npar)
        try:
            r=least_squares(lambda p: f(p,t,A)-dA_dt, p0, max_nfev=3000)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    return best, np.mean(best.fun**2)/V
